class AbstractQueryPreparerBlankNodePreflightTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void laterFixedAlgebraReferenceIsReservedBeforeEarlierFreshAllocation() {
		String fixedId = "preflight-0";
		ParsedUpdate parsed = new ParsedUpdate();
		parsed.addUpdateExpr(insertWith(new BNodeGenerator(), "fresh"));
		parsed.addUpdateExpr(insertWith(new ValueConstant(VF.createBNode(fixedId)), "fixed"));
		RecordingPreparer preparer = new RecordingPreparer(parsed.getUpdateExprs().get(0));
		BlankNodeAllocationScope scope = new BlankNodeAllocationScope("preflight-", ignored -> false);

		try (var activation = scope.activate()) {
			preparer.prepare(parsed).execute();
		}

		assertEquals(2, preparer.executed.size());
		assertEquals("preflight-1", preparer.generated.get(0).getID(),
				"the earlier fresh allocation must skip the fixed ID used by a later update expression");
	}

	@Test
	void everyUpdateOperationRunsInsideOneAllocationScope() {
		ParsedUpdate parsed = new ParsedUpdate();
		parsed.addUpdateExpr(insertWith(new BNodeGenerator(), "first"));
		parsed.addUpdateExpr(insertWith(new BNodeGenerator(), "second"));
		RecordingPreparer preparer = new RecordingPreparer(parsed.getUpdateExprs().get(0));

		preparer.prepare(parsed).execute();

		assertEquals(2, preparer.scopes.size());
		assertSame(preparer.scopes.get(0), preparer.scopes.get(1),
				"all operations in one parsed update must share one execution allocation scope");
	}

	@Test
	void malformedLaterDataIsRejectedBeforeAnyOperationExecutes() {
		ParsedUpdate parsed = new ParsedUpdate();
		parsed.addUpdateExpr(new InsertData("_:fresh <urn:p> \"first\" ."));
		parsed.addUpdateExpr(new InsertData("?s <urn:p> ?o ."));
		RecordingPreparer preparer = new RecordingPreparer(parsed.getUpdateExprs().get(0));

		assertThrows(RuntimeException.class, () -> preparer.prepare(parsed).execute());
		assertEquals(List.of(), preparer.executed,
				"the whole update must be validated before any operation can produce a side effect");
	}

	private static Modify insertWith(ValueExpr value, String name) {
		Extension template = new Extension(new SingletonSet(), new ExtensionElem(value, name));
		return new Modify(null, template, new SingletonSet());
	}

	private static final class RecordingPreparer extends AbstractQueryPreparer {
		private final List<UpdateExpr> executed = new ArrayList<>();
		private final List<BlankNodeAllocationScope> scopes = new ArrayList<>();
		private final List<BNode> generated = new ArrayList<>();
		private final UpdateExpr firstExpression;

		private RecordingPreparer(UpdateExpr firstExpression) {
			super(new TripleSource() {
				@Override
				public ValueFactory getValueFactory() {
					return VF;
				}

				@Override
				public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate,
						Value object, Resource... contexts) {
					return new EmptyIteration<>();
				}
			});
			this.firstExpression = firstExpression;
		}

		@Override
		protected CloseableIteration<? extends BindingSet> evaluate(TupleExpr tupleExpr,
				Dataset dataset, BindingSet bindings, boolean includeInferred, int maxExecutionTime)
				throws QueryEvaluationException {
			return new EmptyIteration<>();
		}

		@Override
		protected void execute(UpdateExpr updateExpr, Dataset dataset, BindingSet bindings, boolean includeInferred,
				int maxExecutionTime) {
			executed.add(updateExpr);
			BlankNodeAllocationScope allocation = BlankNodeAllocationScope.currentOrNew();
			scopes.add(allocation);
			if (updateExpr == firstExpression) {
				generated.add(allocation.createBNode(VF));
			}
		}
	}
}
